		fakeImageProvider: &fakeImageProvider{
			available: true,
			result: ImageProviderResult{
				Provider:  "codex",
				ImageURL:  "/tmp/codex-test.png",
				MediaType: "image/png",
			},
		},
	}
	runner := NewImageGenRunner(ImageGenConfig{
		Provider:     "codex",
		DefaultModel: "fal-ai/flux-2/klein/9b",
